# S403 · esboços 69a (VIP sutil em Minha conta), 69b (reserva de 3 h do VIP), 69c (reserva cancelada sem e-mail). Pedido do dono 17/11 10:43. Nada implementado.
E=open('esb2.py').read();exec(E[:E.index('with sync_playwright')])
SUT="""()=>{const h=[...document.querySelectorAll('#layer h1,#layer h2,#layer h3')].find(e=>/Minha conta/.test(e.textContent));const p=document.createElement('p');p.style.cssText='margin:-6px 0 14px;font:500 14px Inter,system-ui,sans-serif;color:#6b5f66';p.innerHTML='Carlos Benítez <span style="color:#a9854a;margin:0 6px">·</span><span style="color:#8a6a33;font-weight:600">✦ Cliente VIP</span>';const par=h.parentNode;if(getComputedStyle(par).display.includes('flex')){par.parentNode.insertBefore(p,par.nextSibling);p.style.margin='-4px 0 14px'}else h.parentNode.insertBefore(p,h.nextSibling);return !!h}"""
R3="""()=>{const c=document.getElementById('cdx');c.innerHTML='<span>Reservada para você até</span><span class="zk"><b>13:40</b></span>';const f=c.nextElementSibling;if(f&&f.classList.contains('zf'))f.outerHTML='<p class="vipn" style="margin:6px 0 10px"><b>✦ Cliente VIP:</b> sua reserva é de 3 horas.</p>'}"""
CAN="""()=>{const e=document.querySelector('[data-id=kitped1]');const w=document.createTreeWalker(e,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(/Pedido cancelado/.test(n.nodeValue))n.nodeValue=n.nodeValue.replace('Pedido cancelado','Reserva cancelada')}
 const p=document.createElement('p');p.style.cssText='margin:8px 0 0;font:13.5px/1.5 Inter,system-ui,sans-serif;color:#6b5f66';p.textContent='Nada foi cobrado. As peças voltaram para o site; se ainda estiverem disponíveis, é só fazer o pedido de novo.';e.style.flexWrap='wrap';p.style.flexBasis='100%';e.appendChild(p)}"""
with sync_playwright() as pw:
    par('s',cart(VIP),[SUT],900)
    par('r',lambda:pag.abre(pw,'pix',0.2),[R3],844,prep=VCX)
    par('k',lambda:pago.abre(pw,'pedidos','cancelado'),[CAN],844)
P('69a-site-minha-conta-vip-sutil.jpg','Esboço 69a · Site · Minha conta · Cliente VIP (sutil)',['Hoje: nada mostra que o cliente é VIP.','Proposta (refaz o 68a, recusado): só uma linha pequena abaixo de "Minha conta": o nome e "✦ Cliente VIP" em dourado. Sem cartão de status; as vantagens aparecem onde acontecem.'],T+'s_h.png',T+'s_p.png')
P('69b-site-pagamento-reserva-3h-vip.jpg','Esboço 69b · Site · Pagamento · reserva de 3 horas do VIP',['Hoje: reserva de 30 minutos com o relógio, para todos.','Proposta (refaz o 68d): o VIP tem 3 horas, e a tela mostra o horário ("até 13:40"). Uma reserva por vez. Você pode cancelar no app enquanto não estiver pago. Nenhum e-mail.'],T+'r_h.png',T+'r_p.png')
P('69c-site-pedidos-reserva-cancelada.jpg','Esboço 69c · Site · Minha conta › Pedidos · reserva cancelada ou vencida',['Hoje: "Pedido cancelado", sem explicação.','Proposta: quando a reserva vence ou você cancela antes do pagamento, o cliente vê isto em Minha conta, e não recebe e-mail. O e-mail de cancelado (63b) só sai para pedido já pago.'],T+'k_h.png',T+'k_p.png')
